/* Reasoning-effort prefixes, verbatim from the DeepSeek-V4-Flash-0731 reference
 * encoder (encoding/encoding_dsv4.py, REASONING_EFFORT_PROMPTS).  Upstream's
 * "low" is the empty string, so it needs no constant here.  Both are injected
 * at the very start of the conversation, ahead of the system message, which is
 * where the reference encoder puts them (render_message: index == 0 and
 * thinking_mode == "thinking"). */
static const char DS4_REASONING_EFFORT_HIGH_PREFIX[] =
    "Reasoning Effort: Absolute maximum with no shortcuts permitted.\n"
    "You MUST be very thorough in your thinking and comprehensively decompose the problem to resolve the root cause, rigorously stress-testing your logic against all potential paths, edge cases, and adversarial scenarios.\n"
    "Explicitly write out your entire deliberation process, documenting every intermediate step, considered alternative, and rejected hypothesis to ensure absolutely no assumption is left unchecked.\n\n";

static const char DS4_REASONING_EFFORT_MAX_PREFIX[] =
    "Reasoning Effort: Beyond maximum — exhaustive, relentless, and uncompromising.\n"
    "You MUST reason with the utmost depth and rigor, leaving absolutely nothing to chance: exhaustively decompose the problem into its most fundamental components, trace every causal chain to its root, and resolve the underlying cause rather than any surface symptom.\n"
    "Do not stop reasoning until you have independently verified the solution from multiple angles and are certain that no assumption remains unchecked and no error remains undiscovered.\n\n";

static bool ds4_backend_uses_graph(ds4_backend backend) {
    return backend == DS4_BACKEND_METAL || backend == DS4_BACKEND_CUDA;
}

/* =========================================================================
 * DeepSeek V4 Shape Profiles.
 * =========================================================================
 *
 * The weight binder and metadata validator select one of the known model
 * profiles below.  Arrays reserve the maximum Pro dimensions; hot loops read
 * the active profile after GGUF validation.
 */

enum {
    DS4_MAX_LAYER            = 61,
    /* Phase 2 Step 4d: maximum concurrent sequences the per-seq compressor
     * emit bookkeeping (ms_* arrays) is sized for.  The multi-seq batched
     * decode emit indexes per-(seq,layer) state banks + row counters; this
     * caps the self-test / future generation fan-out.  Small fixed bound. */
    DS4_MULTISEQ_MAX_SEQ     = 128,
    /* S1.1 M3 / D4.5d: number of per-bank speculative-rollback checkpoint depths.
     * The verify forward snapshots each bank's compressor state after committing a
     * 1..DS4_MTP_RB_DEPTH-token prefix, so a partial accept of M kept tokens
     * (M <= DS4_MTP_RB_DEPTH) restores from depth M-1 with no re-forward.  =2 was
     * enough for MTP depth<=2; the DSpark block of 5 accepts up to 4 drafts, so the
     * lossless in-forward-emit+rollback path needs 4 checkpoint depths. */
    DS4_MTP_RB_DEPTH         = 4,
    DS4_MAX_EMBD             = 7168,
    DS4_MAX_VOCAB            = 129280,
    DS4_MAX_HEAD             = 128,
    DS4_MAX_HEAD_KV          = 1,
    DS4_MAX_HEAD_DIM         = 512,
    DS4_MAX_VALUE_DIM        = 512,
    DS4_MAX_ROT              = 64,
    DS4_MAX_OUT_GROUP        = 16,
    DS4_MAX_LORA_Q           = 1536,
    DS4_MAX_LORA_O           = 1024,
    DS4_MAX_EXPERT           = 384,
    DS4_MAX_EXPERT_USED      = 6,
    DS4_MAX_EXPERT_SHARED    = 1,
    DS4_MAX_FF_EXP           = 3072,
    DS4_MAX_HASH_LAYER       = 3,
    DS4_MAX_SWA              = 128,
    DS4_MAX_INDEXER_HEAD     = 64,
    DS4_MAX_INDEXER_HEAD_DIM = 128,
    DS4_MAX_INDEXER_TOP_K    = 1024,
    DS4_MAX_HC               = 4,
    DS4_MAX_HC_SINKHORN_ITER = 20,
};

